const item = $input.item.json;
const fmt = (item.display_format || item.media_type || '').toLowerCase();
const isVideo = fmt.includes('video');
const ext = isVideo ? 'mp4' : 'jpg';
const contentType = isVideo ? 'video/mp4' : 'image/jpeg';
const slug = (item.brand_name || 'unknown').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const assetPath = slug + '/' + item.id + '.' + ext;
const hasMedia = !!(item.media_url || item.thumbnail_url);
const thumbForClassify = item.thumbnail_url || item.media_url || 'https://placehold.co/1x1/png';
const mainUrl = item.media_url || 'https://placehold.co/1x1/png';
return { json: { ...item, _ext: ext, _contentType: contentType, _assetPath: assetPath, _hasMedia: hasMedia, _thumbForClassify: thumbForClassify, _mainUrl: mainUrl } };

const ad = $('Prepare Paths').item.json;
const bin = $input.item.binary && $input.item.binary.thumb;
const isRealBase64 = bin && bin.data && typeof bin.data === 'string' && bin.data.length > 500 && !bin.data.startsWith('filesystem');
const hasImage = ad._hasMedia && isRealBase64;
const parts = [{ text: ['You are a senior creative strategist analyzing a Meta (Facebook/Instagram) advertisement.','Use BOTH the image (if provided) AND the ad text. Be specific — vague answers are useless.','','AD DATA:','BRAND: ' + (ad.brand_name || 'unknown'),'FORMAT: ' + (ad.display_format || 'unknown') + (ad.media_type ? ' / ' + ad.media_type : ''),'TITLE: ' + (ad.title || '(none)'),'BODY: ' + (ad.body || '(none)'),'CTA: ' + (ad.cta_type || '') + ' — ' + (ad.cta_text || ''),'','FIELD DEFINITIONS:','','ad_type — pick ONE: UGC_TESTIMONIAL | FOUNDER_STORY | US_VS_THEM | PRODUCT_DEMO | BEFORE_AFTER | FAQ | PROMO_DISCOUNT | OTHER','funnel_stage — pick ONE: TOF | MOF | BOF','hook: EXACT opening line verbatim. Max 200 chars.','core_angle: one sentence — the central persuasive claim. Max 300 chars.','target_persona: specific (e.g. "Women 25-45 who want fuller lips without injections")','pain_point: specific problem or desire being addressed.','emotional_tone: dominant emotional register (e.g. "urgency + social proof")','visual_description: 2-3 sentences on scene, product, visuals. Empty if no image.','talent_description: gender, age range, skin tone, hair, expression, wardrobe. Empty if no people.','color_palette: 3-5 dominant colors. Empty if no image.','shot_style: camera/composition description. Empty if no image.','on_screen_text: exact text visible in image. Empty if none.','creative_brief: 3-5 sentences for a creative director to recreate this ad from scratch.','confidence: 0-1 overall classification confidence.','','5 LIGHTBULBS FRAMEWORK (persuasion journey analysis):','lightbulb_status_quo: What is the prospect currently doing or believing that keeps them stuck?','lightbulb_alternatives: What other solutions has the prospect tried or considered?','lightbulb_mechanism: What is the unique mechanism or approach this ad introduces?','lightbulb_offer: What is the specific offer, CTA, or next step presented?','lightbulb_new_life: What transformation or outcome does the ad promise?','','native_ui_hijacking: true if ad mimics iOS notifications, TikTok comment overlays, or other native OS/app UI elements. false otherwise.','hook_timing_seconds: float — at what second does the core value prop land? 0 for static images.'].join('\n') }];
if (hasImage) parts.push({ inline_data: { mime_type: bin.mimeType || 'image/jpeg', data: bin.data } });
const geminiBody = { contents: [{ parts }], generationConfig: { responseMimeType: 'application/json', responseSchema: { type: 'OBJECT', properties: { ad_type: { type: 'STRING', enum: ['UGC_TESTIMONIAL','FOUNDER_STORY','US_VS_THEM','PRODUCT_DEMO','BEFORE_AFTER','FAQ','PROMO_DISCOUNT','OTHER'] }, funnel_stage: { type: 'STRING', enum: ['TOF','MOF','BOF'] }, hook: { type: 'STRING' }, core_angle: { type: 'STRING' }, target_persona: { type: 'STRING' }, pain_point: { type: 'STRING' }, emotional_tone: { type: 'STRING' }, visual_description: { type: 'STRING' }, talent_description: { type: 'STRING' }, color_palette: { type: 'STRING' }, shot_style: { type: 'STRING' }, on_screen_text: { type: 'STRING' }, creative_brief: { type: 'STRING' }, confidence: { type: 'NUMBER' }, lightbulb_status_quo: { type: 'STRING' }, lightbulb_alternatives: { type: 'STRING' }, lightbulb_mechanism: { type: 'STRING' }, lightbulb_offer: { type: 'STRING' }, lightbulb_new_life: { type: 'STRING' }, native_ui_hijacking: { type: 'BOOLEAN' }, hook_timing_seconds: { type: 'NUMBER' } }, required: ['ad_type','funnel_stage','hook','core_angle','confidence','creative_brief','lightbulb_status_quo','lightbulb_mechanism','lightbulb_new_life'] }, temperature: 0.2 } };
return { json: { ...ad, _geminiBody: geminiBody, _hadImage: hasImage } };

const ad = $('Prepare Paths').item.json;
const resp = $input.item.json;
let parsed = null; let err = null;
try {
  const text = resp && resp.candidates && resp.candidates[0] && resp.candidates[0].content && resp.candidates[0].content.parts && resp.candidates[0].content.parts[0] && resp.candidates[0].content.parts[0].text;
  if (!text) throw new Error('No Gemini text: ' + JSON.stringify(resp).slice(0,300));
  parsed = JSON.parse(text);
} catch(e) { err = e.message; }
const e = parsed || {};
const embedText = ['Brand:' + (ad.brand_name||''), 'Format:' + (ad.display_format||''), 'Type:' + (e.ad_type||''), 'Funnel:' + (e.funnel_stage||''), 'Hook:' + (e.hook||''), 'Angle:' + (e.core_angle||''), 'Persona:' + (e.target_persona||''), 'Pain:' + (e.pain_point||''), 'Tone:' + (e.emotional_tone||''), 'Visual:' + (e.visual_description||''), 'Talent:' + (e.talent_description||''), 'Colors:' + (e.color_palette||''), 'Shot:' + (e.shot_style||''), 'OnScreen:' + (e.on_screen_text||''), 'Brief:' + (e.creative_brief||''), 'SQ:' + (e.lightbulb_status_quo||''), 'Mech:' + (e.lightbulb_mechanism||''), 'NewLife:' + (e.lightbulb_new_life||''), 'Title:' + (ad.title||''), 'Body:' + (ad.body||'')].join(' | ');
return { json: { id: ad.id, brand_id: ad.brand_id||null, _mainUrl: ad._mainUrl, _hasMedia: ad._hasMedia, _ext: ad._ext, _contentType: ad._contentType, _assetPath: ad._assetPath, _enrichment: parsed, _enrichment_error: err, _embedText: embedText, _embedBody: { requests: [{ model: 'models/gemini-embedding-2', content: { parts: [{ text: embedText }] }, taskType: 'RETRIEVAL_DOCUMENT' }] } } };

const prev = $('Parse + Build Embed Text').item.json;
const resp = $input.item.json;
let values = null; let err = prev._enrichment_error || null;
try {
  values = resp && resp.embeddings && resp.embeddings[0] && Array.isArray(resp.embeddings[0].values) ? resp.embeddings[0].values : null;
  if (!values) throw new Error('No embedding values: ' + JSON.stringify(resp).slice(0,300));
} catch(e) { err = (err ? err + ' | ' : '') + 'embed:' + e.message; }
const pgvec = values ? '[' + values.map(function(v){ return Number(v).toFixed(6); }).join(',') + ']' : null;
return { json: { ...prev, _embedding: pgvec, _enrichment_error: err } };
